/// <reference path="./manga-provider.d.ts" />

class Provider {
    private baseUrl = "https://mangafire.to";

    getSettings(): Settings {
        return {
            supportsMultiLanguage: true,
            supportsMultiScanlator: true,
        };
    }

    private async request(url: string): Promise<any> {
        const response = await fetch(url, {
            method: "GET",
            headers: {
                "Accept": "application/json",
                "Referer": this.baseUrl + "/",
            },
        });

        if (!response.ok) {
            throw new Error("MangaFire HTTP " + response.status);
        }

        return await response.json();
    }

    private extractMangaId(url: string): string {
        const value = String(url || "").split("?")[0].replace(/\/+$/, "");

        if (value.indexOf("/title/") >= 0) {
            const last = value.substring(value.lastIndexOf("/") + 1);
            return last.split("-")[0];
        }

        if (value.indexOf("/manga/") >= 0) {
            const last = value.substring(value.lastIndexOf("/") + 1);
            const dot = last.lastIndexOf(".");
            if (dot >= 0) {
                return last.substring(dot + 1);
            }
        }

        return "";
    }

    async search(opts: QueryOptions): Promise<SearchResult[]> {
        const url =
            this.baseUrl +
            "/api/titles?keyword=" +
            encodeURIComponent(opts.query) +
            "&language=en&limit=30&page=1";

        const json = await this.request(url);
        const items = json && Array.isArray(json.items)
            ? json.items
            : [];

        const results: SearchResult[] = [];

        for (let i = 0; i < items.length; i++) {
            const item = items[i];
            const sourceUrl = item && item.url
                ? String(item.url)
                : "";

            const id = this.extractMangaId(sourceUrl);
            const title = item && item.title
                ? String(item.title)
                : "";

            if (!id || !title) {
                continue;
            }

            const result: SearchResult = {
                id: id,
                title: title,
                synonyms: [],
            };

            if (
                item.poster &&
                typeof item.poster === "object" &&
                item.poster.medium
            ) {
                result.image = String(item.poster.medium);
            }

            results.push(result);
        }

        return results;
    }

    async findChapters(mangaId: string): Promise<ChapterDetails[]> {
        const chapters: ChapterDetails[] = [];
        const seen: { [key: string]: boolean } = {};

        let page = 1;
        let hasNext = true;

        while (hasNext && page <= 100) {
            const url =
                this.baseUrl +
                "/api/titles/" +
                encodeURIComponent(mangaId) +
                "/chapters" +
                "?language=en&sort=number&order=desc&limit=200&page=" +
                page;

            const json = await this.request(url);

            if (!json || !Array.isArray(json.items)) {
                break;
            }

            const items = json.items;

            for (let i = 0; i < items.length; i++) {
                const item = items[i];

                if (!item || item.id === undefined || item.id === null) {
                    continue;
                }

                const chapterId = String(item.id);

                if (seen[chapterId]) {
                    continue;
                }

                seen[chapterId] = true;

                const number = item.number !== undefined &&
                    item.number !== null
                    ? String(item.number)
                    : "";

                let title = "Chapter";
                if (number) {
                    title = "Ch. " + number;
                }
                if (item.name) {
                    title += ": " + String(item.name);
                }

                const chapter: ChapterDetails = {
                    id: chapterId,
                    url:
                        this.baseUrl +
                        "/title/" +
                        encodeURIComponent(mangaId) +
                        "/" +
                        encodeURIComponent(chapterId),
                    title: title,
                    chapter: number,
                    index: 0,
                };

                if (item.type === "official") {
                    chapter.scanlator = "official";
                }

                if (item.language) {
                    chapter.language = String(item.language);
                } else {
                    chapter.language = "en";
                }

                if (
                    item.createdAt !== undefined &&
                    item.createdAt !== null
                ) {
                    const timestamp = Number(item.createdAt);
                    if (!isNaN(timestamp) && timestamp > 0) {
                        chapter.updatedAt =
                            new Date(timestamp * 1000).toISOString();
                    }
                }

                chapters.push(chapter);
            }

            hasNext =
                !!json.meta &&
                json.meta.hasNext === true;

            page++;
        }

        // MangaFire returns newest first.
        // Seanime requires ascending chapter indexes.
        chapters.reverse();

        for (let i = 0; i < chapters.length; i++) {
            chapters[i].index = i;
        }

        return chapters;
    }

    async findChapterPages(chapterId: string): Promise<ChapterPage[]> {
        const json = await this.request(
            this.baseUrl +
            "/api/chapters/" +
            encodeURIComponent(chapterId)
        );

        if (
            !json ||
            !json.data ||
            !Array.isArray(json.data.pages)
        ) {
            return [];
        }

        const pages: ChapterPage[] = [];

        for (let i = 0; i < json.data.pages.length; i++) {
            const page = json.data.pages[i];

            if (!page || !page.url) {
                continue;
            }

            pages.push({
                url: String(page.url),
                index: pages.length,
                headers: {
                    "Referer": this.baseUrl + "/",
                },
            });
        }

        return pages;
    }
}
